/**
 * Which mutation a response is being read as. A melt mints nothing and so
 * owes no signature; a split mints two notes and owes one over each.
 */

enum class FfiMutationKind {
    
    MELT,
    ROTATE,
    SPLIT,
    MERGE;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiMutationKind: FfiConverterRustBuffer<FfiMutationKind> {
    override fun read(buf: ByteBuffer) = try {
        FfiMutationKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiMutationKind) = 4UL

    override fun write(value: FfiMutationKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * The error taxonomy, flattened for the bindings. The distinction that matters
 * is the same one it is in Rust: [`LnurlcashError::Ambiguous`] means the
 * request MAY have been processed, and nothing may be assumed.
 */
sealed class LnurlcashException: kotlin.Exception() {
    
    /**
     * Nothing was sent. The note is untouched.
     */
    class RequestRefused(
        
        val `detail`: kotlin.String
        ) : LnurlcashException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A non-mutating response did not match the spec.
     */
    class Protocol(
        
        val `detail`: kotlin.String
        ) : LnurlcashException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The service processed the request and refused it. Definitive.
     */
    class ServiceRejected(
        
        val `reason`: kotlin.String
        ) : LnurlcashException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A melt is in flight on this k1. Retry - never read this as spent.
     */
    class NotePending(
        ) : LnurlcashException() {
        override val message
            get() = ""
    }
    
    /**
     * Authoritative: the note is already burned.
     */
    class NoteSpent(
        
        val `reason`: kotlin.String, 
        
        val `newSecrets`: List<kotlin.String>
        ) : LnurlcashException() {
        override val message
            get() = "reason=${ `reason` }, newSecrets=${ `newSecrets` }"
    }
    
    /**
     * The service does not recognise this note.
     */
    class NoteUnknown(
        
        val `reason`: kotlin.String, 
        
        val `newSecrets`: List<kotlin.String>
        ) : LnurlcashException() {
        override val message
            get() = "reason=${ `reason` }, newSecrets=${ `newSecrets` }"
    }
    
    /**
     * The outcome is UNKNOWN. Preserve any secrets the request carried.
     */
    class Ambiguous(
        
        val `detail`: kotlin.String, 
        
        val `newSecrets`: List<kotlin.String>
        ) : LnurlcashException() {
        override val message
            get() = "detail=${ `detail` }, newSecrets=${ `newSecrets` }"
    }
    
    /**
     * The mutation LANDED and the SERVICE returned no signature over it.
     * LUD-25 requires one, so this is a non-conforming SERVICE - but the note
     * exists at the hash the wallet disclosed, and `new_secrets` is the only
     * key to it. Persist them before deciding anything else.
     */
    class Unverifiable(
        
        val `detail`: kotlin.String, 
        
        val `newSecrets`: List<kotlin.String>
        ) : LnurlcashException() {
        override val message
            get() = "detail=${ `detail` }, newSecrets=${ `newSecrets` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LnurlcashException> {
        override fun lift(error_buf: RustBuffer.ByValue): LnurlcashException = FfiConverterTypeLnurlcashError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLnurlcashError : FfiConverterRustBuffer<LnurlcashException> {
    override fun read(buf: ByteBuffer): LnurlcashException {
        

        return when(buf.getInt()) {
            1 -> LnurlcashException.RequestRefused(
                FfiConverterString.read(buf),
                )
            2 -> LnurlcashException.Protocol(
                FfiConverterString.read(buf),
                )
            3 -> LnurlcashException.ServiceRejected(
                FfiConverterString.read(buf),
                )
            4 -> LnurlcashException.NotePending()
            5 -> LnurlcashException.NoteSpent(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            6 -> LnurlcashException.NoteUnknown(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            7 -> LnurlcashException.Ambiguous(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            8 -> LnurlcashException.Unverifiable(
                FfiConverterString.read(buf),
                FfiConverterSequenceString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LnurlcashException): ULong {
        return when(value) {
            is LnurlcashException.RequestRefused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is LnurlcashException.Protocol -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is LnurlcashException.ServiceRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LnurlcashException.NotePending -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LnurlcashException.NoteSpent -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterSequenceString.allocationSize(value.`newSecrets`)
            )
            is LnurlcashException.NoteUnknown -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterSequenceString.allocationSize(value.`newSecrets`)
            )
            is LnurlcashException.Ambiguous -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
                + FfiConverterSequenceString.allocationSize(value.`newSecrets`)
            )
            is LnurlcashException.Unverifiable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
                + FfiConverterSequenceString.allocationSize(value.`newSecrets`)
            )
        }
    }

    override fun write(value: LnurlcashException, buf: ByteBuffer) {
        when(value) {
            is LnurlcashException.RequestRefused -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is LnurlcashException.Protocol -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is LnurlcashException.ServiceRejected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LnurlcashException.NotePending -> {
                buf.putInt(4)
                Unit
            }
            is LnurlcashException.NoteSpent -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterSequenceString.write(value.`newSecrets`, buf)
                Unit
            }
            is LnurlcashException.NoteUnknown -> {
                buf.putInt(6)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterSequenceString.write(value.`newSecrets`, buf)
                Unit
            }
            is LnurlcashException.Ambiguous -> {
                buf.putInt(7)
                FfiConverterString.write(value.`detail`, buf)
                FfiConverterSequenceString.write(value.`newSecrets`, buf)
                Unit
            }
            is LnurlcashException.Unverifiable -> {
                buf.putInt(8)
                FfiConverterString.write(value.`detail`, buf)
                FfiConverterSequenceString.write(value.`newSecrets`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalULong: FfiConverterRustBuffer<kotlin.ULong?> {
    override fun read(buf: ByteBuffer): kotlin.ULong? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterULong.read(buf)
    }

    override fun allocationSize(value: kotlin.ULong?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterULong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ULong?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterULong.write(value, buf)
        }
    }
}




